t("You must be able to move to use %s!", "Tú debe ser capaz de moverse a utilizar %s!", "logPlayer")
t("%s is not usable while wearing heavy armour.", "%s no es usable mientras usas armadura pesada.", "logPlayer")
t("Disengage", "Separación", "talent name")
t("You must disengage directly away from your target in a straight line.", "Debes desconectar directamente de tu objetivo en una línea recta.", "logPlayer")
t("You must land in an empty space.", "Debes aterrizar en un espacio vacío.", "logPlayer")
t("Your Disengage was partially blocked.", "Tu separación fue bloqueada parcialmente.", "logPlayer")
t("You are not able to Disengage in that direction.", "No eres capaz de desconectar en esa dirección.", "logPlayer")
t("Evasion", "Evasión", "talent name")
t("Tumble", "Voltereta", "talent name")
t("You must have an empty space to roll to.", "Debes tener un espacio vacío para rodar.", "logPlayer")
t("Trained Reactions", "Reacciones entrenadas", "talent name")
t("#FIREBRICK##Target# reacts to %s from #Source#, mitigating the blow!#LAST#.", "#FIREBRICK# #Target# reacciona a %s desde #Source#, mitigando el golpe! #LAST#.", "logCombat")
